require "application_system_test_case"

class EdgeCasesTest < ApplicationSystemTestCase
  test "remove option row renumbers and single active question preview shows See score immediately" do
    authenticate_as_moderator

    quiz = Quiz.create!(title: "Edge Quiz")
    q1 = quiz.questions.build(body: "Pick any prime", active: true)
    q1.save_with_option_rows([
      Question::OptionRow.new(id: nil, body: "2", correct: true),
      Question::OptionRow.new(id: nil, body: "4", correct: false),
      Question::OptionRow.new(id: nil, body: "5", correct: true)
    ])
    q2 = quiz.questions.build(body: "Inactive Q", active: false)
    q2.save_with_option_rows([
      Question::OptionRow.new(id: nil, body: "X", correct: true),
      Question::OptionRow.new(id: nil, body: "Y", correct: false)
    ])

    visit moderate_quiz_path(quiz)

    # First question Move up disabled, last question Move down disabled
    items = all("ul.question-list > li")
    within(items[0]) do
      assert_button "Move up", disabled: true
      assert_button "Move down", disabled: false
    end
    within(items[1]) do
      assert_button "Move up", disabled: false
      assert_button "Move down", disabled: true
    end

    # Preview with 1 active question and multiple correct options
    click_link "Preview"
    assert_text "Question 1 of 1"
    assert_text "Pick any prime"
    click_button "5"
    assert_text "Correct!"
    # Both 2 and 5 should be marked is-correct
    assert_selector ".play-option.is-correct", count: 2
    click_button "See score"
    assert_text "Score: 1/1"

    click_link "Back to quiz"

    # Add question and test removing row renumbers
    click_link "Add question"
    click_button "Remove option 2"
    assert_field "Option 1"
    assert_field "Option 2"
    assert_field "Option 3"
    assert_no_field "Option 4"

    click_button "Add option"
    assert_field "Option 4"
  end

  test "preview with zero active questions shows empty message" do
    authenticate_as_moderator
    quiz = Quiz.create!(title: "Empty Preview")

    visit preview_moderate_quiz_path(quiz)
    assert_text "No active questions to preview."
    click_link "Back to quiz"
    assert_selector "h1", text: "Empty Preview"
  end
end
"
}

